-- Generated by npm run tags:build. Do not edit by hand.
--
-- Initial, conservative tag backfill. Existing D1 tags are preserved and the
-- migration is idempotent, so it is safe to retry after an interrupted rollout.

DROP TABLE IF EXISTS _tag_catalog_seed_0007;
CREATE TABLE _tag_catalog_seed_0007 (
  scope TEXT NOT NULL CHECK(scope IN ('work', 'song')),
  id TEXT NOT NULL,
  tags TEXT NOT NULL CHECK(json_valid(tags)),
  PRIMARY KEY (scope, id)
);



























UPDATE works
SET tags = (
  SELECT json_group_array(value)
  FROM (
    SELECT DISTINCT value
    FROM (
      SELECT value FROM json_each(
        CASE WHEN json_valid(works.tags) THEN works.tags ELSE '[]' END
      )
      UNION ALL
      SELECT value FROM json_each((
        SELECT seed.tags
        FROM _tag_catalog_seed_0007 AS seed
        WHERE seed.scope = 'work' AND seed.id = works.id
      ))
    )
    ORDER BY value
  )
),
updated_at = datetime('now')
WHERE EXISTS (
  SELECT 1 FROM _tag_catalog_seed_0007 AS seed
  WHERE seed.scope = 'work' AND seed.id = works.id
);

UPDATE songs
SET tags = (
  SELECT json_group_array(value)
  FROM (
    SELECT DISTINCT value
    FROM (
      SELECT value FROM json_each(
        CASE WHEN json_valid(songs.tags) THEN songs.tags ELSE '[]' END
      )
      UNION ALL
      SELECT value FROM json_each((
        SELECT seed.tags
        FROM _tag_catalog_seed_0007 AS seed
        WHERE seed.scope = 'song' AND seed.id = songs.id
      ))
    )
    ORDER BY value
  )
),
updated_at = datetime('now')
WHERE EXISTS (
  SELECT 1 FROM _tag_catalog_seed_0007 AS seed
  WHERE seed.scope = 'song' AND seed.id = songs.id
);

DROP TABLE _tag_catalog_seed_0007;
